head.script:
scwin.createMouseEvent = function(ev, type) {
    if (ev.initMouseEvent) {
        if (WebSquare.util.isIE(9) || WebSquare.util.isIE(10)) {
            if (type.slice(0, 2) != "on") {
                type = "on" + type;
            }
            if (document.createEventObject) {
                var mouseEvent = document.createEventObject();
                mouseEvent.button = 0;
                ev.target.fireEvent(type, mouseEvent);
            }
        } else {
            var mouseEvent = document.createEvent("MouseEvent");
            if (type.slice(0, 2) == "on") {
                type = type.slice(2);
            }
            mouseEvent.initMouseEvent(type, true, true, window, 0,
                ev.screenX, ev.screenY, ev.clientX, ev.clientY,
                ev.ctrlKey, ev.altKey, ev.shiftKey, ev.metaKey,
                0, null);
            ev.target.dispatchEvent(mouseEvent);
        }
    } else {
        if (type.slice(0, 2) != "on") {
            type = "on" + type;
        }
        if (document.createEventObject) {
            var mouseEvent = document.createEventObject();
            mouseEvent.button = 0;
            WebSquare.wUnit.getDomById($p.id + ev).fireEvent(type, mouseEvent);
        }
    }
}
scwin.createDblClickEvent = function(ev) {
    scwin.createMouseEvent(ev, "onmousedown");
    scwin.createMouseEvent(ev, "onmouseup");
    scwin.createMouseEvent(ev, "onclick");
    scwin.createMouseEvent(ev, "onmousedown");
    scwin.createMouseEvent(ev, "onmouseup");
    scwin.createMouseEvent(ev, "onclick");
    scwin.createMouseEvent(ev, "ondblclick");
}
scwin.__triggerKeyboardEvent = function(el, keyCode) {
    var eventObj = document.createEventObject ?
        document.createEventObject() : document.createEvent("Events");
    if (eventObj.initEvent) {
        eventObj.initEvent("keydown", true, true);
    }
    eventObj.keyCode = keyCode;
    eventObj.which = keyCode;
    el.dispatchEvent ? el.dispatchEvent(eventObj) : el.fireEvent("onkeydown", eventObj);
}
scwin.callFun = function() {
    scwin.createDblClickEvent(evtObj['gridView1_cell_2_1']);
}
scwin.callFun2 = function() {
    scwin.__triggerKeyboardEvent(WebSquare.wUnit.getDomById('G_'+$p.id+'gridView1__col2'), 13);
}
scwin.callFun3 = function() {
    scwin.createDblClickEvent(evtObj['gridView1_cell_3_1']);
}
scwin.unitTest = function() {
    var cell21 = "gridView1_cell_2_1";
    var cell31 = "gridView1_cell_3_1";
    window.evtObj = {};
    WebSquare.wUnit.getDomById($p.id + cell21).onclick = function(ev) {
        evtObj[cell21] = ev;
    };
    WebSquare.wUnit.getDomById($p.id + cell31).onclick = function(ev) {
        evtObj[cell31] = ev;
    };
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'gridView1_cell_2_1').click()");
    WebSquare.wUnit.addCommand("set", "scwin.callFun()");
    WebSquare.wUnit.addCommand("pause", "50");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_gridView1__col2').setValue('12')");
    WebSquare.wUnit.addCommand("pause", "50");
    WebSquare.wUnit.addCommand("set", "scwin.callFun2()");
    WebSquare.wUnit.addCommand("pause", "50");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'gridView1_cell_3_1').click()");
    WebSquare.wUnit.addCommand("set", "scwin.callFun3()");
    WebSquare.wUnit.addCommand("pause", "50");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_gridView1__col2').setValue('25')");
    WebSquare.wUnit.addCommand("pause", "50");
    WebSquare.wUnit.addCommand("set", "scwin.callFun2()");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'gridView1_cell_2_1').querySelector('nobr').innerHTML === '25'", "false");
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
